import { AssetViewer } from './viewer.js';
import {
  extractFilesFromDataTransfer,
  loadAssetFromFiles,
  loadAssetFromUrl,
} from './loaders.js';

const viewportEl = document.getElementById('viewport');
const emptyStateEl = document.getElementById('empty-state');
const dropOverlayEl = document.getElementById('drop-overlay');
const loadingOverlayEl = document.getElementById('loading-overlay');
const loadingTextEl = document.getElementById('loading-text');
const toastEl = document.getElementById('toast');
const fileBadgeEl = document.getElementById('file-badge');
const inspectorEl = document.getElementById('inspector');

const fileInput = document.getElementById('file-input');
const btnOpen = document.getElementById('btn-open');
const btnEmptyOpen = document.getElementById('btn-empty-open');
const btnDemo = document.getElementById('btn-demo');
const btnEmptyDemo = document.getElementById('btn-empty-demo');
const btnScreenshot = document.getElementById('btn-screenshot');
const btnTogglePanel = document.getElementById('btn-toggle-panel');
const btnResetCam = document.getElementById('btn-reset-cam');

const statMeshes = document.getElementById('stat-meshes');
const statVertices = document.getElementById('stat-vertices');
const statTriangles = document.getElementById('stat-triangles');
const statMaterials = document.getElementById('stat-materials');
const statDims = document.getElementById('stat-dims');

const sectionAnimations = document.getElementById('section-animations');
const animSelect = document.getElementById('anim-select');
const btnAnimPlay = document.getElementById('btn-anim-play');
const animSpeed = document.getElementById('anim-speed');
const animSpeedVal = document.getElementById('anim-speed-val');

const chkWireframe = document.getElementById('chk-wireframe');
const chkGrid = document.getElementById('chk-grid');
const chkAxes = document.getElementById('chk-axes');
const chkBbox = document.getElementById('chk-bbox');
const chkAutorotate = document.getElementById('chk-autorotate');
const chkFlat = document.getElementById('chk-flat');

const bgPreset = document.getElementById('bg-preset');
const sliderExposure = document.getElementById('slider-exposure');
const valExposure = document.getElementById('val-exposure');
const sliderEnv = document.getElementById('slider-env');
const valEnv = document.getElementById('val-env');
const sliderLight = document.getElementById('slider-light');
const valLight = document.getElementById('val-light');

const viewer = new AssetViewer(viewportEl);
let currentAssetName = 'demo-asset';
let toastTimer = null;

function formatNumber(n) {
  return n.toLocaleString();
}

function showLoading(message = 'Loading model...') {
  loadingTextEl.textContent = message;
  loadingOverlayEl.classList.remove('hidden');
}

function hideLoading() {
  loadingOverlayEl.classList.add('hidden');
}

function showToast(message) {
  toastEl.textContent = message;
  toastEl.classList.remove('hidden');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => {
    toastEl.classList.add('hidden');
  }, 5000);
}

function updateInspector({ name, format, stats, animations }) {
  currentAssetName = name;
  emptyStateEl.classList.add('hidden');

  fileBadgeEl.textContent = format ? `${name} (${format})` : name;
  fileBadgeEl.classList.remove('hidden');

  statMeshes.textContent = formatNumber(stats.meshes);
  statVertices.textContent = formatNumber(stats.vertices);
  statTriangles.textContent = formatNumber(stats.triangles);
  statMaterials.textContent = formatNumber(stats.materials);

  const { x, y, z } = stats.size;
  statDims.textContent = `${x.toFixed(2)} × ${y.toFixed(2)} × ${z.toFixed(2)}`;

  // Reset bounding box checkbox to match viewer state
  chkBbox.checked = false;

  // Animations UI
  if (animations && animations.length > 0) {
    sectionAnimations.classList.remove('hidden');
    animSelect.innerHTML = '';
    animations.forEach((clipName, idx) => {
      const opt = document.createElement('option');
      opt.value = String(idx);
      opt.textContent = clipName;
      animSelect.appendChild(opt);
    });
    btnAnimPlay.textContent = 'Pause';
  } else {
    sectionAnimations.classList.add('hidden');
  }
}

async function handleFiles(files) {
  if (!files || files.length === 0) return;
  showLoading(`Loading ${files.length === 1 ? files[0].name : `${files.length} files`}...`);
  try {
    const asset = await loadAssetFromFiles(files);
    const info = viewer.setModel(asset.object, asset.animations, asset.cleanup);
    updateInspector({
      name: asset.name,
      format: asset.format,
      stats: info.stats,
      animations: info.animations,
    });
  } catch (err) {
    console.error(err);
    showToast(err?.message || 'Failed to load 3D asset.');
  } finally {
    hideLoading();
  }
}

async function handleUrl(url) {
  showLoading(`Loading ${url}...`);
  try {
    const asset = await loadAssetFromUrl(url);
    const info = viewer.setModel(asset.object, asset.animations, asset.cleanup);
    updateInspector({
      name: asset.name,
      format: asset.format,
      stats: info.stats,
      animations: info.animations,
    });
  } catch (err) {
    console.error(err);
    showToast(err?.message || `Failed to load asset from ${url}`);
  } finally {
    hideLoading();
  }
}

function loadDemo() {
  const info = viewer.loadDemoAsset();
  updateInspector({
    name: 'Demo Torus Knot',
    format: 'PBR',
    stats: info.stats,
    animations: info.animations,
  });
}

// File picker triggers
const openPicker = () => fileInput.click();
btnOpen.addEventListener('click', openPicker);
btnEmptyOpen.addEventListener('click', openPicker);

fileInput.addEventListener('change', (e) => {
  if (e.target.files?.length) {
    handleFiles(e.target.files);
    fileInput.value = '';
  }
});

// Demo triggers
btnDemo.addEventListener('click', loadDemo);
btnEmptyDemo.addEventListener('click', loadDemo);

// Screenshot
btnScreenshot.addEventListener('click', () => {
  const base = currentAssetName.replace(/\.[^.]+$/, '');
  viewer.takeScreenshot(`${base}.png`);
});

// Toggle Inspector Panel
btnTogglePanel.addEventListener('click', () => {
  inspectorEl.classList.toggle('collapsed');
});

// Display toggles
chkWireframe.addEventListener('change', (e) => viewer.setWireframe(e.target.checked));
chkGrid.addEventListener('change', (e) => viewer.setGridVisible(e.target.checked));
chkAxes.addEventListener('change', (e) => viewer.setAxesVisible(e.target.checked));
chkBbox.addEventListener('change', (e) => viewer.setBoundingBoxVisible(e.target.checked));
chkAutorotate.addEventListener('change', (e) => viewer.setAutoRotate(e.target.checked));
chkFlat.addEventListener('change', (e) => viewer.setFlatShading(e.target.checked));

// Lighting & Scene controls
bgPreset.addEventListener('change', (e) => viewer.setBackdrop(e.target.value));

sliderExposure.addEventListener('input', (e) => {
  const v = parseFloat(e.target.value);
  valExposure.textContent = v.toFixed(2);
  viewer.setExposure(v);
});

sliderEnv.addEventListener('input', (e) => {
  const v = parseFloat(e.target.value);
  valEnv.textContent = v.toFixed(2);
  viewer.setEnvironmentIntensity(v);
});

sliderLight.addEventListener('input', (e) => {
  const v = parseFloat(e.target.value);
  valLight.textContent = v.toFixed(2);
  viewer.setKeyLightIntensity(v);
});

// Animation controls
animSelect.addEventListener('change', (e) => {
  viewer.playAnimation(Number(e.target.value));
  btnAnimPlay.textContent = 'Pause';
});

btnAnimPlay.addEventListener('click', () => {
  const next = !viewer.isPlaying;
  viewer.setAnimationPlaying(next);
  btnAnimPlay.textContent = next ? 'Pause' : 'Play';
});

animSpeed.addEventListener('input', (e) => {
  const v = parseFloat(e.target.value);
  animSpeedVal.textContent = `${v.toFixed(1)}x`;
  viewer.setAnimationSpeed(v);
});

// Camera presets
document.querySelectorAll('[data-cam]').forEach((btn) => {
  btn.addEventListener('click', () => {
    viewer.setCameraPreset(btn.dataset.cam);
  });
});

btnResetCam.addEventListener('click', () => viewer.setCameraPreset('iso'));

// Drag & Drop support (files + folders)
let dragDepth = 0;

window.addEventListener('dragenter', (e) => {
  e.preventDefault();
  dragDepth += 1;
  dropOverlayEl.classList.remove('hidden');
});

window.addEventListener('dragover', (e) => {
  e.preventDefault();
  if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
});

window.addEventListener('dragleave', (e) => {
  e.preventDefault();
  dragDepth = Math.max(0, dragDepth - 1);
  if (dragDepth === 0) {
    dropOverlayEl.classList.add('hidden');
  }
});

window.addEventListener('drop', async (e) => {
  e.preventDefault();
  dragDepth = 0;
  dropOverlayEl.classList.add('hidden');

  if (e.dataTransfer) {
    const files = await extractFilesFromDataTransfer(e.dataTransfer);
    handleFiles(files);
  }
});

// Keyboard shortcuts
window.addEventListener('keydown', (e) => {
  if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;

  const key = e.key.toLowerCase();
  if (key === 'r') {
    viewer.setCameraPreset('iso');
  } else if (key === 'w') {
    chkWireframe.checked = !chkWireframe.checked;
    viewer.setWireframe(chkWireframe.checked);
  } else if (key === 'i') {
    inspectorEl.classList.toggle('collapsed');
  } else if (key === 'o') {
    openPicker();
  }
});

// Optional URL query parameter (?url=/path/to/model.glb)
const params = new URLSearchParams(window.location.search);
const initialUrl = params.get('url');
if (initialUrl) {
  handleUrl(initialUrl);
}
