import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader.js';
import { MeshoptDecoder } from 'three/examples/jsm/libs/meshopt_decoder.module.js';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader.js';
import { MTLLoader } from 'three/examples/jsm/loaders/MTLLoader.js';
import { PLYLoader } from 'three/examples/jsm/loaders/PLYLoader.js';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
import { STLLoader } from 'three/examples/jsm/loaders/STLLoader.js';
import { ColladaLoader } from 'three/examples/jsm/loaders/ColladaLoader.js';
import { TDSLoader } from 'three/examples/jsm/loaders/TDSLoader.js';

export const SUPPORTED_MODEL_EXTENSIONS = [
  'glb',
  'gltf',
  'obj',
  'ply',
  'fbx',
  'stl',
  'dae',
  '3ds',
];

function getExtension(filename) {
  const clean = filename.split('?')[0].split('#')[0];
  const dot = clean.lastIndexOf('.');
  return dot >= 0 ? clean.slice(dot + 1).toLowerCase() : '';
}

function normalizePath(p) {
  return decodeURIComponent(p)
    .replace(/\\/g, '/')
    .replace(/^\.?\//, '')
    .toLowerCase();
}

function basename(p) {
  const norm = normalizePath(p);
  const idx = norm.lastIndexOf('/');
  return idx >= 0 ? norm.slice(idx + 1) : norm;
}

function createDefaultMaterial(hasVertexColors = false) {
  return new THREE.MeshStandardMaterial({
    color: hasVertexColors ? 0xffffff : 0xc8cfd8,
    roughness: 0.55,
    metalness: 0.1,
    vertexColors: hasVertexColors,
    side: THREE.DoubleSide,
  });
}

function buildMeshOrPointsFromGeometry(geometry) {
  const hasColors = Boolean(geometry.getAttribute('color'));
  const hasFaces =
    (geometry.index && geometry.index.count > 0) ||
    (!geometry.index && geometry.getAttribute('position')?.count >= 3 && !geometry.userData?.isPointCloud);

  // PLY files can be pure point clouds (no index and no normals)
  if (!geometry.index && !geometry.getAttribute('normal') && geometry.userData?.isPly) {
    const mat = new THREE.PointsMaterial({
      size: 0.015,
      sizeAttenuation: true,
      vertexColors: hasColors,
      color: hasColors ? 0xffffff : 0xd0d8e4,
    });
    return new THREE.Points(geometry, mat);
  }

  if (!hasFaces) {
    const mat = new THREE.PointsMaterial({
      size: 0.015,
      sizeAttenuation: true,
      vertexColors: hasColors,
      color: hasColors ? 0xffffff : 0xd0d8e4,
    });
    return new THREE.Points(geometry, mat);
  }

  if (!geometry.getAttribute('normal')) {
    geometry.computeVertexNormals();
  }

  const mesh = new THREE.Mesh(geometry, createDefaultMaterial(hasColors));
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function createGLTFLoader(manager) {
  const loader = new GLTFLoader(manager);
  const dracoLoader = new DRACOLoader(manager);
  dracoLoader.setDecoderPath('/draco/');
  loader.setDRACOLoader(dracoLoader);
  loader.setMeshoptDecoder(MeshoptDecoder);
  return { loader, dracoLoader };
}

/**
 * Load a 3D asset from a list of dropped/selected File objects.
 * Supports multi-file assets such as .gltf + .bin + textures or .obj + .mtl + textures.
 */
export async function loadAssetFromFiles(files) {
  const fileList = Array.from(files);
  if (fileList.length === 0) {
    throw new Error('No files provided.');
  }

  // Find the primary 3D model file
  const primaryFile = fileList.find((f) =>
    SUPPORTED_MODEL_EXTENSIONS.includes(getExtension(f.name))
  );

  if (!primaryFile) {
    throw new Error(
      `Unsupported file format. Supported formats: ${SUPPORTED_MODEL_EXTENSIONS.map((e) => '.' + e).join(', ')}`
    );
  }

  const ext = getExtension(primaryFile.name);
  const blobUrls = [];
  const pathToUrl = new Map();
  const baseToUrl = new Map();

  for (const file of fileList) {
    const url = URL.createObjectURL(file);
    blobUrls.push(url);

    const rel = file.webkitRelativePath || file.name;
    pathToUrl.set(normalizePath(rel), url);
    pathToUrl.set(normalizePath(file.name), url);
    baseToUrl.set(basename(rel), url);
  }

  const manager = new THREE.LoadingManager();
  manager.setURLModifier((url) => {
    if (url.startsWith('blob:') || url.startsWith('data:') || /^https?:\/\//i.test(url)) {
      return url;
    }
    const norm = normalizePath(url);
    if (pathToUrl.has(norm)) return pathToUrl.get(norm);

    const base = basename(url);
    if (baseToUrl.has(base)) return baseToUrl.get(base);

    return url;
  });

  const primaryUrl = pathToUrl.get(normalizePath(primaryFile.webkitRelativePath || primaryFile.name));
  const mtlFile =
    ext === 'obj'
      ? fileList.find((f) => getExtension(f.name) === 'mtl')
      : null;
  const mtlUrl = mtlFile
    ? pathToUrl.get(normalizePath(mtlFile.webkitRelativePath || mtlFile.name))
    : null;

  try {
    const result = await loadByExtension({
      ext,
      url: primaryUrl,
      mtlUrl,
      manager,
    });

    return {
      ...result,
      name: primaryFile.name,
      format: ext.toUpperCase(),
      cleanup: () => {
        blobUrls.forEach((u) => URL.revokeObjectURL(u));
      },
    };
  } catch (err) {
    blobUrls.forEach((u) => URL.revokeObjectURL(u));
    throw err;
  }
}

/**
 * Load a 3D asset directly from a URL (e.g. ?url=/model.glb).
 */
export async function loadAssetFromUrl(url) {
  const ext = getExtension(url);
  if (!SUPPORTED_MODEL_EXTENSIONS.includes(ext)) {
    throw new Error(`Unsupported URL format ".${ext}".`);
  }

  const manager = new THREE.LoadingManager();
  const result = await loadByExtension({ ext, url, mtlUrl: null, manager });
  const name = decodeURIComponent(url.split('/').pop().split('?')[0] || `model.${ext}`);

  return {
    ...result,
    name,
    format: ext.toUpperCase(),
    cleanup: () => {},
  };
}

async function loadByExtension({ ext, url, mtlUrl, manager }) {
  switch (ext) {
    case 'glb':
    case 'gltf': {
      const { loader, dracoLoader } = createGLTFLoader(manager);
      try {
        const gltf = await loader.loadAsync(url);
        return {
          object: gltf.scene || gltf.scenes[0],
          animations: gltf.animations || [],
        };
      } finally {
        dracoLoader.dispose();
      }
    }

    case 'obj': {
      const objLoader = new OBJLoader(manager);
      if (mtlUrl) {
        const mtlLoader = new MTLLoader(manager);
        const materials = await mtlLoader.loadAsync(mtlUrl);
        materials.preload();
        objLoader.setMaterials(materials);
      }
      const object = await objLoader.loadAsync(url);
      // Apply a clean default PBR material if no MTL was provided
      if (!mtlUrl) {
        object.traverse((child) => {
          if (child.isMesh) {
            const hasColors = Boolean(child.geometry?.getAttribute('color'));
            child.material = createDefaultMaterial(hasColors);
          }
        });
      }
      return { object, animations: [] };
    }

    case 'ply': {
      const loader = new PLYLoader(manager);
      const geometry = await loader.loadAsync(url);
      geometry.userData.isPly = true;
      const obj = buildMeshOrPointsFromGeometry(geometry);
      return { object: obj, animations: [] };
    }

    case 'fbx': {
      const loader = new FBXLoader(manager);
      const object = await loader.loadAsync(url);
      return { object, animations: object.animations || [] };
    }

    case 'stl': {
      const loader = new STLLoader(manager);
      const geometry = await loader.loadAsync(url);
      const obj = buildMeshOrPointsFromGeometry(geometry);
      return { object: obj, animations: [] };
    }

    case 'dae': {
      const loader = new ColladaLoader(manager);
      const collada = await loader.loadAsync(url);
      return {
        object: collada.scene,
        animations: collada.scene.animations || [],
      };
    }

    case '3ds': {
      const loader = new TDSLoader(manager);
      const object = await loader.loadAsync(url);
      return { object, animations: [] };
    }

    default:
      throw new Error(`No loader registered for ".${ext}".`);
  }
}

/**
 * Recursively collect File objects from DataTransferItems (supports folders!).
 */
export async function extractFilesFromDataTransfer(dataTransfer) {
  const items = dataTransfer.items;
  if (!items || items.length === 0) {
    return Array.from(dataTransfer.files || []);
  }

  const files = [];

  async function readEntry(entry, pathPrefix = '') {
    if (entry.isFile) {
      await new Promise((resolve, reject) => {
        entry.file((file) => {
          if (pathPrefix && !file.webkitRelativePath) {
            Object.defineProperty(file, 'webkitRelativePath', {
              value: `${pathPrefix}${file.name}`,
              configurable: true,
            });
          }
          files.push(file);
          resolve();
        }, reject);
      });
    } else if (entry.isDirectory) {
      const reader = entry.createReader();
      const readBatch = () =>
        new Promise((resolve, reject) => {
          reader.readEntries(resolve, reject);
        });

      let entries = await readBatch();
      while (entries.length > 0) {
        for (const child of entries) {
          await readEntry(child, `${pathPrefix}${entry.name}/`);
        }
        entries = await readBatch();
      }
    }
  }

  const entries = [];
  for (const item of items) {
    if (item.kind === 'file') {
      const entry = item.webkitGetAsEntry?.();
      if (entry) {
        entries.push(entry);
      } else {
        const f = item.getAsFile();
        if (f) files.push(f);
      }
    }
  }

  for (const entry of entries) {
    await readEntry(entry);
  }

  return files;
}

/**
 * Compute mesh, vertex, triangle, and material counts for an Object3D.
 */
export function computeAssetStats(root) {
  let meshes = 0;
  let vertices = 0;
  let triangles = 0;
  const materials = new Set();

  root.traverse((child) => {
    if (child.isMesh || child.isPoints || child.isLine) {
      meshes += 1;
      const geo = child.geometry;
      if (geo) {
        const pos = geo.getAttribute('position');
        if (pos) vertices += pos.count;
        if (child.isMesh) {
          if (geo.index) {
            triangles += Math.floor(geo.index.count / 3);
          } else if (pos) {
            triangles += Math.floor(pos.count / 3);
          }
        }
      }
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      mats.forEach((m) => {
        if (m) materials.add(m);
      });
    }
  });

  const box = new THREE.Box3().setFromObject(root);
  const size = new THREE.Vector3();
  box.getSize(size);

  return {
    meshes,
    vertices,
    triangles,
    materials: materials.size,
    size,
  };
}

/**
 * Dispose all geometries, materials, and textures under an Object3D.
 */
export function disposeObject(root) {
  if (!root) return;
  root.traverse((child) => {
    if (child.geometry) {
      child.geometry.dispose();
    }
    if (child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      for (const mat of mats) {
        if (!mat) continue;
        for (const value of Object.values(mat)) {
          if (value && typeof value === 'object' && value.isTexture) {
            value.dispose();
          }
        }
        mat.dispose();
      }
    }
  });
}
