import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';
import { computeAssetStats, disposeObject } from './loaders.js';

const BACKDROP_PRESETS = {
  studio: {
    bg: 0x161920,
    gridCenter: 0x454d5e,
    gridLines: 0x262b36,
  },
  neutral: {
    bg: 0x3b4048,
    gridCenter: 0x626a78,
    gridLines: 0x4b525e,
  },
  light: {
    bg: 0xe6e9ef,
    gridCenter: 0x9aa3b2,
    gridLines: 0xc9cfd9,
  },
  midnight: {
    bg: 0x090b10,
    gridCenter: 0x28324a,
    gridLines: 0x151a26,
  },
};

export class AssetViewer {
  constructor(container) {
    this.container = container;
    this.clock = new THREE.Clock();

    this.currentModelGroup = null;
    this.currentCleanup = null;
    this.boxHelper = null;
    this.mixer = null;
    this.animations = [];
    this.activeAction = null;
    this.isPlaying = true;
    this.animSpeed = 1.0;

    this.wireframe = false;
    this.flatShading = false;
    this.modelRadius = 1.5;
    this.modelCenter = new THREE.Vector3(0, 0.5, 0);

    this._initScene();
    this._initLights();
    this._initHelpers();
    this._bindResize();
    this._animate();
  }

  _initScene() {
    const width = this.container.clientWidth || window.innerWidth;
    const height = this.container.clientHeight || window.innerHeight;

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(BACKDROP_PRESETS.studio.bg);

    this.camera = new THREE.PerspectiveCamera(45, width / height, 0.01, 2000);
    this.camera.position.set(2.8, 2.0, 3.2);

    this.renderer = new THREE.WebGLRenderer({
      antialias: true,
      preserveDrawingBuffer: true,
      powerPreference: 'high-performance',
    });
    this.renderer.setSize(width, height);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.0;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    this.container.appendChild(this.renderer.domElement);

    // Procedural Studio IBL Environment
    const pmremGenerator = new THREE.PMREMGenerator(this.renderer);
    this.envRenderTarget = pmremGenerator.fromScene(new RoomEnvironment(), 0.04);
    this.scene.environment = this.envRenderTarget.texture;
    this.scene.environmentIntensity = 1.0;
    pmremGenerator.dispose();

    // OrbitControls
    this.controls = new OrbitControls(this.camera, this.renderer.domElement);
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.06;
    this.controls.screenSpacePanning = true;
    this.controls.minDistance = 0.05;
    this.controls.maxDistance = 500;
    this.controls.target.set(0, 0.5, 0);
    this.controls.update();
  }

  _initLights() {
    this.hemiLight = new THREE.HemisphereLight(0xffffff, 0x2a2f3d, 0.45);
    this.scene.add(this.hemiLight);

    this.keyLight = new THREE.DirectionalLight(0xffffff, 1.5);
    this.keyLight.position.set(4, 7, 5);
    this.keyLight.castShadow = true;
    this.keyLight.shadow.mapSize.set(2048, 2048);
    this.keyLight.shadow.camera.near = 0.1;
    this.keyLight.shadow.camera.far = 40;
    const d = 5;
    this.keyLight.shadow.camera.left = -d;
    this.keyLight.shadow.camera.right = d;
    this.keyLight.shadow.camera.top = d;
    this.keyLight.shadow.camera.bottom = -d;
    this.keyLight.shadow.bias = -0.0005;
    this.scene.add(this.keyLight);

    this.rimLight = new THREE.DirectionalLight(0x9ec5ff, 0.5);
    this.rimLight.position.set(-5, 3, -4);
    this.scene.add(this.rimLight);
  }

  _initHelpers() {
    this.gridHelper = new THREE.GridHelper(
      12,
      24,
      BACKDROP_PRESETS.studio.gridCenter,
      BACKDROP_PRESETS.studio.gridLines
    );
    this.gridHelper.position.y = 0;
    this.scene.add(this.gridHelper);

    this.axesHelper = new THREE.AxesHelper(1.5);
    this.axesHelper.visible = false;
    this.scene.add(this.axesHelper);

    // Subtle shadow-receiving ground plane
    const shadowGeo = new THREE.PlaneGeometry(24, 24);
    const shadowMat = new THREE.ShadowMaterial({ opacity: 0.22 });
    this.shadowPlane = new THREE.Mesh(shadowGeo, shadowMat);
    this.shadowPlane.rotation.x = -Math.PI / 2;
    this.shadowPlane.position.y = -0.001;
    this.shadowPlane.receiveShadow = true;
    this.scene.add(this.shadowPlane);
  }

  _bindResize() {
    this._onResize = () => {
      const width = this.container.clientWidth || window.innerWidth;
      const height = this.container.clientHeight || window.innerHeight;
      this.camera.aspect = width / height;
      this.camera.updateProjectionMatrix();
      this.renderer.setSize(width, height);
    };
    window.addEventListener('resize', this._onResize);
  }

  _animate() {
    this._rafId = requestAnimationFrame(() => this._animate());
    const dt = this.clock.getDelta();

    if (this.mixer && this.isPlaying) {
      this.mixer.update(dt * this.animSpeed);
      if (this.boxHelper && this.boxHelper.visible) {
        this.boxHelper.update();
      }
    }

    this.controls.update();
    this.renderer.render(this.scene, this.camera);
  }

  clearModel() {
    if (this.mixer) {
      this.mixer.stopAllAction();
      this.mixer = null;
    }
    this.animations = [];
    this.activeAction = null;

    if (this.boxHelper) {
      this.scene.remove(this.boxHelper);
      this.boxHelper.dispose();
      this.boxHelper = null;
    }

    if (this.currentModelGroup) {
      this.scene.remove(this.currentModelGroup);
      disposeObject(this.currentModelGroup);
      this.currentModelGroup = null;
    }

    if (this.currentCleanup) {
      this.currentCleanup();
      this.currentCleanup = null;
    }
  }

  /**
   * Mount a loaded Three.js Object3D, normalize its scale & center it on the floor,
   * set up animations, and frame the camera.
   */
  setModel(object, animations = [], cleanup = null) {
    this.clearModel();
    this.currentCleanup = cleanup;

    // Measure original dimensions before normalization
    object.updateMatrixWorld(true);
    const originalStats = computeAssetStats(object);

    const wrapper = new THREE.Group();
    wrapper.add(object);

    // Enable shadows and apply current display flags
    object.traverse((child) => {
      if (child.isMesh) {
        child.castShadow = true;
        child.receiveShadow = true;
      }
    });

    // Compute bounds and normalize to a comfortable ~2.4 unit bounding sphere
    const box = new THREE.Box3().setFromObject(object);
    const size = new THREE.Vector3();
    const center = new THREE.Vector3();
    box.getSize(size);
    box.getCenter(center);

    const maxDim = Math.max(size.x, size.y, size.z);
    const targetSize = 2.4;
    const scale = maxDim > 0 ? targetSize / maxDim : 1;

    object.scale.multiplyScalar(scale);
    object.position.sub(center.multiplyScalar(scale));

    // Place bottom of bounding box cleanly on y = 0
    wrapper.updateMatrixWorld(true);
    const normalizedBox = new THREE.Box3().setFromObject(wrapper);
    wrapper.position.y -= normalizedBox.min.y;

    this.currentModelGroup = wrapper;
    this.scene.add(wrapper);

    // Recompute final bounds for framing and BoxHelper
    wrapper.updateMatrixWorld(true);
    const finalBox = new THREE.Box3().setFromObject(wrapper);
    const finalSphere = new THREE.Sphere();
    finalBox.getBoundingSphere(finalSphere);

    this.modelCenter.copy(finalSphere.center);
    this.modelRadius = Math.max(finalSphere.radius, 0.25);

    this.boxHelper = new THREE.BoxHelper(wrapper, 0x4f8cff);
    this.boxHelper.visible = false;
    this.scene.add(this.boxHelper);

    // Apply current wireframe / flat shading state
    this.setWireframe(this.wireframe);
    this.setFlatShading(this.flatShading);

    // Animations
    this.animations = animations || [];
    if (this.animations.length > 0) {
      this.mixer = new THREE.AnimationMixer(object);
      this.playAnimation(0);
    }

    this.setCameraPreset('iso');

    return {
      stats: originalStats,
      animations: this.animations.map((clip, i) => clip.name || `Clip ${i + 1}`),
    };
  }

  /**
   * Create a procedural PBR demo asset so the user can immediately test the viewer.
   */
  loadDemoAsset() {
    const group = new THREE.Group();

    const knotGeo = new THREE.TorusKnotGeometry(0.7, 0.24, 180, 32);
    const knotMat = new THREE.MeshStandardMaterial({
      color: 0x4f8cff,
      metalness: 0.72,
      roughness: 0.22,
    });
    const knot = new THREE.Mesh(knotGeo, knotMat);
    knot.position.y = 1.05;
    group.add(knot);

    const baseGeo = new THREE.CylinderGeometry(0.95, 1.05, 0.14, 48);
    const baseMat = new THREE.MeshStandardMaterial({
      color: 0x2c323f,
      metalness: 0.3,
      roughness: 0.55,
    });
    const base = new THREE.Mesh(baseGeo, baseMat);
    base.position.y = 0.07;
    group.add(base);

    return this.setModel(group, []);
  }

  playAnimation(index) {
    if (!this.mixer || !this.animations[index]) return;
    if (this.activeAction) {
      this.activeAction.stop();
    }
    this.activeAction = this.mixer.clipAction(this.animations[index]);
    this.activeAction.reset().play();
    this.isPlaying = true;
  }

  setAnimationPlaying(playing) {
    this.isPlaying = playing;
  }

  setAnimationSpeed(speed) {
    this.animSpeed = speed;
  }

  setWireframe(enabled) {
    this.wireframe = enabled;
    if (!this.currentModelGroup) return;
    this.currentModelGroup.traverse((child) => {
      if (child.isMesh && child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach((m) => {
          if ('wireframe' in m) m.wireframe = enabled;
        });
      }
    });
  }

  setFlatShading(enabled) {
    this.flatShading = enabled;
    if (!this.currentModelGroup) return;
    this.currentModelGroup.traverse((child) => {
      if (child.isMesh && child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach((m) => {
          if ('flatShading' in m) {
            m.flatShading = enabled;
            m.needsUpdate = true;
          }
        });
      }
    });
  }

  setGridVisible(visible) {
    this.gridHelper.visible = visible;
    this.shadowPlane.visible = visible;
  }

  setAxesVisible(visible) {
    this.axesHelper.visible = visible;
  }

  setBoundingBoxVisible(visible) {
    if (this.boxHelper) {
      this.boxHelper.visible = visible;
    }
  }

  setAutoRotate(enabled) {
    this.controls.autoRotate = enabled;
    this.controls.autoRotateSpeed = 2.0;
  }

  setBackdrop(presetKey) {
    const preset = BACKDROP_PRESETS[presetKey] || BACKDROP_PRESETS.studio;
    this.scene.background = new THREE.Color(preset.bg);

    const visible = this.gridHelper.visible;
    this.scene.remove(this.gridHelper);
    this.gridHelper.geometry.dispose();
    this.gridHelper.material.dispose();

    this.gridHelper = new THREE.GridHelper(12, 24, preset.gridCenter, preset.gridLines);
    this.gridHelper.visible = visible;
    this.scene.add(this.gridHelper);
  }

  setExposure(value) {
    this.renderer.toneMappingExposure = value;
  }

  setEnvironmentIntensity(value) {
    this.scene.environmentIntensity = value;
  }

  setKeyLightIntensity(value) {
    this.keyLight.intensity = value;
  }

  setCameraPreset(preset) {
    const fovRad = THREE.MathUtils.degToRad(this.camera.fov);
    const dist = (this.modelRadius / Math.sin(fovRad / 2)) * 1.18;
    const c = this.modelCenter;

    const dirs = {
      front: new THREE.Vector3(0, 0.15, 1),
      back: new THREE.Vector3(0, 0.15, -1),
      left: new THREE.Vector3(-1, 0.15, 0),
      right: new THREE.Vector3(1, 0.15, 0),
      top: new THREE.Vector3(0, 1, 0.01),
      iso: new THREE.Vector3(0.85, 0.58, 0.95),
    };

    const dir = (dirs[preset] || dirs.iso).clone().normalize();
    this.camera.position.copy(c).addScaledVector(dir, dist);
    this.camera.near = Math.max(dist / 500, 0.005);
    this.camera.far = Math.max(dist * 100, 500);
    this.camera.updateProjectionMatrix();

    this.controls.target.copy(c);
    this.controls.update();
  }

  takeScreenshot(filename = 'asset-screenshot.png') {
    this.renderer.render(this.scene, this.camera);
    const dataUrl = this.renderer.domElement.toDataURL('image/png');
    const a = document.createElement('a');
    a.href = dataUrl;
    a.download = filename;
    a.click();
  }

  dispose() {
    cancelAnimationFrame(this._rafId);
    window.removeEventListener('resize', this._onResize);
    this.clearModel();
    this.controls.dispose();
    this.envRenderTarget.dispose();
    this.renderer.dispose();
  }
}
